const headers = $json.headers || {};
const query = $json.query || {};
const authHeader = headers.authorization || headers.Authorization || '';
const hasBearerToken = String(authHeader).toLowerCase().startsWith('bearer ');
const allowedPipelines = new Set(['all', 'generation', 'ingestion']);
const pipeline = allowedPipelines.has(String(query.pipeline || 'all')) ? String(query.pipeline || 'all') : 'all';
const daysRaw = Number.parseInt(String(query.days || '30'), 10);
const days = Number.isFinite(daysRaw) ? Math.min(Math.max(daysRaw, 1), 365) : 30;
const dateFrom = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString();
return [{ json: { isAuthorized: hasBearerToken, token: hasBearerToken ? String(authHeader).replace(/^Bearer\s+/i, '') : '', pipeline, days, dateFrom, userIdFilter: query.userId || '', projectIdFilter: query.projectId || '' } }];

const context = $('Prepare Analytics Context').first().json;
const authUser = $('Verify Supabase Auth User').first().json;
const profile = $('Fetch Q-Ops User Profile').first().json || {};
const memberships = $input.all()
  .map(item => item.json)
  .filter(row => row && row.project_id)
  .map(row => ({ projectId: row.project_id, role: row.project_role || 'viewer' }));

if (!profile.id || profile.status !== 'active') throw new Error('Active Q-Ops user profile not found');

const pairs = [];
function add(name, value) {
  pairs.push(`${encodeURIComponent(name)}=${encodeURIComponent(value)}`);
}

add('select', 'job_id,project_name,document_type,pipeline,event,status,duration_ms,word_count,chunk_count,total_files,tokens_input,tokens_output,tokens_total,estimated_cost_usd,error_message,metadata,created_at,requested_by,project_id');
add('created_at', `gte.${context.dateFrom}`);
add('order', 'created_at.desc');
add('limit', '1000');

if (context.pipeline !== 'all') add('pipeline', `eq.${context.pipeline}`);

let scope = 'workspace';
let requestedByFilter = '';
let assignedProjectIds = [];

if (profile.role === 'registered_user') {
  requestedByFilter = profile.id;
  assignedProjectIds = memberships.map(item => item.projectId);
  scope = 'self_assigned_projects';
} else if (profile.role === 'admin' && context.userIdFilter) {
  requestedByFilter = context.userIdFilter;
  scope = 'admin_user_filter';
}

if (requestedByFilter) add('requested_by', `eq.${requestedByFilter}`);

if (context.projectIdFilter) {
  if (profile.role === 'registered_user' && !assignedProjectIds.includes(context.projectIdFilter)) {
    add('project_id', 'eq.__no_assigned_project__');
  } else {
    add('project_id', `eq.${context.projectIdFilter}`);
  }
} else if (profile.role === 'registered_user') {
  if (assignedProjectIds.length) {
    add('project_id', `in.(${assignedProjectIds.map(encodeURIComponent).join(',')})`);
  } else {
    add('project_id', 'eq.__no_assigned_project__');
  }
}

return [{
  json: {
    url: `https://ifnznfspkjayhnooncrv.supabase.co/rest/v1/qa_job_metrics?${pairs.join('&')}`,
    context,
    authUser,
    profile,
    scope,
    assignedProjectIds,
    memberships
  }
}];

const queryContext = $('Build Scoped Metrics Query').first().json;
const context = queryContext.context;
const profile = queryContext.profile;
const rows = $input.all().map(item => item.json).filter(row => row && row.job_id);

function isCompletedEvent(row) {
  return row.event === 'JOB_COMPLETED' || row.event === 'JOB_COMPLETED_WITH_WARNINGS';
}
const completedRows = rows.filter(isCompletedEvent);
const failedRows = rows.filter(row =>
  row.event === 'JOB_FAILED' ||
  row.event === 'QUALITY_GATE_FAILED' ||
  row.status === 'error'
);
const generationCompleted = completedRows.filter(row => row.pipeline === 'generation');
const ingestionCompleted = completedRows.filter(row => row.pipeline === 'ingestion');
const terminalCount = completedRows.length + failedRows.length;
const successRate = terminalCount ? Math.round((completedRows.length / terminalCount) * 100) : 100;

function sumNumber(items, field) {
  return items.reduce((total, row) => total + (Number(row[field]) || 0), 0);
}

function avgNumber(items, field) {
  const values = items.map(row => Number(row[field]) || 0).filter(value => value > 0);
  return values.length ? Math.round(values.reduce((total, value) => total + value, 0) / values.length) : 0;
}

function roundMoney(value) {
  return Number((Number(value) || 0).toFixed(6));
}

function metadataFileCount(row) {
  const fileKeys = row.metadata?.file_keys;
  if (Array.isArray(fileKeys)) return fileKeys.length;
  if (typeof fileKeys === 'string' && fileKeys.trim()) {
    return fileKeys.split(',').map(item => item.trim()).filter(Boolean).length;
  }
  return Number(row.total_files) || 0;
}

const byTypeMap = new Map();
for (const row of generationCompleted) {
  const key = row.document_type || 'unknown';
  const current = byTypeMap.get(key) || {
    documentType: key,
    count: 0,
    tokensTotal: 0,
    estimatedCostUsd: 0
  };
  current.count += 1;
  current.tokensTotal += Number(row.tokens_total) || 0;
  current.estimatedCostUsd += Number(row.estimated_cost_usd) || 0;
  byTypeMap.set(key, current);
}

function failureRateFor(pipeline) {
  const completed = completedRows.filter(row => row.pipeline === pipeline).length;
  const failed = failedRows.filter(row => row.pipeline === pipeline).length;
  const total = completed + failed;
  return total ? Math.round((failed / total) * 100) : 0;
}

const terminalRows = rows
  .filter(row => isCompletedEvent(row) || failedRows.includes(row))
  .sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')));

const recentJobs = terminalRows.slice(0, 100).map(row => {
  const failed = failedRows.includes(row);
  return {
    jobId: row.job_id,
    projectName: row.project_name,
    documentType: row.document_type,
    pipeline: row.pipeline,
    event: row.event,
    status: failed ? 'failed' : row.status,
    durationMs: row.duration_ms,
    wordCount: row.word_count,
    chunkCount: row.chunk_count,
    totalFiles: row.total_files,
    tokensTotal: row.tokens_total || 0,
    estimatedCostUsd: Number(row.estimated_cost_usd) || 0,
    errorMessage: failed ? (row.error_message || row.metadata?.message || row.metadata?.error || null) : null,
    createdAt: row.created_at,
    requestedBy: row.requested_by || null,
    projectId: row.project_id || null
  };
});

const recentFailures = failedRows.slice(0, 10).map(row => ({
  jobId: row.job_id,
  projectName: row.project_name,
  documentType: row.document_type,
  pipeline: row.pipeline || 'unknown',
  event: row.event,
  status: row.status,
  errorMessage: row.error_message || row.metadata?.message || row.metadata?.error || null,
  createdAt: row.created_at,
  requestedBy: row.requested_by || null,
  projectId: row.project_id || null
}));

const recentFailuresByPipelineMap = new Map();
for (const row of failedRows) {
  const key = row.pipeline || 'unknown';
  const current = recentFailuresByPipelineMap.get(key) || {
    pipeline: key,
    count: 0,
    latestFailureAt: row.created_at || null,
    latestJobId: row.job_id || null,
    latestErrorMessage: row.error_message || row.metadata?.message || row.metadata?.error || null
  };
  current.count += 1;
  if (!current.latestFailureAt || String(row.created_at || '') > String(current.latestFailureAt)) {
    current.latestFailureAt = row.created_at || null;
    current.latestJobId = row.job_id || null;
    current.latestErrorMessage = row.error_message || row.metadata?.message || row.metadata?.error || null;
  }
  recentFailuresByPipelineMap.set(key, current);
}

const costByPipelineMap = new Map();
for (const row of rows) {
  const key = row.pipeline || 'unknown';
  const current = costByPipelineMap.get(key) || {
    pipeline: key,
    jobs: 0,
    tokensTotal: 0,
    estimatedCostUsd: 0,
    avgCostUsd: 0
  };
  current.jobs += isCompletedEvent(row) ? 1 : 0;
  current.tokensTotal += Number(row.tokens_total) || 0;
  current.estimatedCostUsd += Number(row.estimated_cost_usd) || 0;
  costByPipelineMap.set(key, current);
}
const costByPipeline = Array.from(costByPipelineMap.values()).map(item => ({
  ...item,
  estimatedCostUsd: roundMoney(item.estimatedCostUsd),
  avgCostUsd: item.jobs ? roundMoney(item.estimatedCostUsd / item.jobs) : 0
}));

const costByProjectMap = new Map();
for (const row of rows) {
  const key = row.project_id || row.project_name || 'unknown';
  const current = costByProjectMap.get(key) || {
    projectId: row.project_id || null,
    projectName: row.project_name || 'Unknown project',
    jobs: 0,
    tokensTotal: 0,
    estimatedCostUsd: 0,
    avgCostUsd: 0
  };
  current.jobs += isCompletedEvent(row) ? 1 : 0;
  current.tokensTotal += Number(row.tokens_total) || 0;
  current.estimatedCostUsd += Number(row.estimated_cost_usd) || 0;
  costByProjectMap.set(key, current);
}
const costByProject = Array.from(costByProjectMap.values())
  .map(item => ({
    ...item,
    estimatedCostUsd: roundMoney(item.estimatedCostUsd),
    avgCostUsd: item.jobs ? roundMoney(item.estimatedCostUsd / item.jobs) : 0
  }))
  .sort((a, b) => b.estimatedCostUsd - a.estimatedCostUsd)
  .slice(0, 10);

const filesByKnowledgeBaseMap = new Map();
for (const row of ingestionCompleted) {
  const key = row.project_id || row.project_name || row.job_id;
  const current = filesByKnowledgeBaseMap.get(key) || {
    projectId: row.project_id || null,
    projectName: row.project_name || 'Unknown knowledge base',
    jobs: 0,
    filesProcessed: 0,
    chunksIngested: 0,
    latestJobId: row.job_id || null,
    latestCompletedAt: row.created_at || null
  };
  current.jobs += 1;
  current.filesProcessed += metadataFileCount(row);
  current.chunksIngested += Number(row.chunk_count) || 0;
  if (!current.latestCompletedAt || String(row.created_at || '') > String(current.latestCompletedAt)) {
    current.latestCompletedAt = row.created_at || null;
    current.latestJobId = row.job_id || null;
  }
  filesByKnowledgeBaseMap.set(key, current);
}
const filesByKnowledgeBase = Array.from(filesByKnowledgeBaseMap.values())
  .sort((a, b) => b.filesProcessed - a.filesProcessed)
  .slice(0, 10);

return [{
  json: {
    overview: {
      totalJobsCompleted: completedRows.length,
      totalDocumentsGenerated: generationCompleted.length,
      totalIngestionJobsCompleted: ingestionCompleted.length,
      totalJobsFailed: failedRows.length,
      successRate,
      totalCostUsd: roundMoney(sumNumber(rows, 'estimated_cost_usd')),
      avgCostPerDocument: generationCompleted.length ? roundMoney(sumNumber(generationCompleted, 'estimated_cost_usd') / generationCompleted.length) : 0,
      totalTokensConsumed: sumNumber(rows, 'tokens_total'),
      totalChunksIngested: sumNumber(rows, 'chunk_count'),
      totalWordsProcessed: sumNumber(completedRows, 'word_count'),
      avgDurationMs: avgNumber(rows, 'duration_ms'),
      avgIngestionDurationMs: avgNumber(ingestionCompleted, 'duration_ms'),
      totalFilesProcessed: ingestionCompleted.reduce((total, row) => total + metadataFileCount(row), 0)
    },
    byDocumentType: Array.from(byTypeMap.values()).map(item => ({
      ...item,
      estimatedCostUsd: roundMoney(item.estimatedCostUsd)
    })),
    failureRate: {
      generation: failureRateFor('generation'),
      ingestion: failureRateFor('ingestion')
    },
    recentJobs,
    ingestion: {
      jobsCompleted: ingestionCompleted.length,
      totalChunksIngested: sumNumber(ingestionCompleted, 'chunk_count'),
      totalWordsProcessed: sumNumber(ingestionCompleted, 'word_count'),
      avgProcessingDurationMs: avgNumber(ingestionCompleted, 'duration_ms'),
      totalFilesProcessed: ingestionCompleted.reduce((total, row) => total + metadataFileCount(row), 0),
      filesByKnowledgeBase
    },
    failures: {
      recent: recentFailures,
      byPipeline: Array.from(recentFailuresByPipelineMap.values())
    },
    costs: {
      byPipeline: costByPipeline,
      byProject: costByProject
    },
    meta: {
      generatedAt: new Date().toISOString(),
      dateFrom: context.dateFrom,
      pipeline: context.pipeline,
      daysRequested: context.days,
      scope: queryContext.scope,
      userRole: profile.role,
      userId: profile.id,
      projectId: context.projectIdFilter || null, assignedProjectIds: queryContext.assignedProjectIds || []
    }
  }
}];
